def warmer(t):
    out = [0] * len(t)
    stack = []
    for i, x in enumerate(t):
        while stack and t[stack[-1]] < x:
            j = stack.pop()
            out[j] = i-j
        stack.append(i)
    return out

def rotate(square):
    n = len(square)
    if any(len(row) != n for row in square):
        raise ValueError("must be square")
    for r in range(n):
        for c in range(r+1, n):
            square[r][c], square[c][r] = square[c][r], square[r][c]
    for row in square:
        row.reverse()

