        raise ValueError("invalid input")
    lo, hi = max(a), sum(a)
    while lo < hi:
        mid = (lo+hi)//2
        groups, total = 1, 0
        for x in a:
            if total+x > mid:
                groups += 1
                total = 0
            total += x
