def cosine(a, b):
    if len(a) != len(b):
        raise ValueError("shape mismatch")
    denom = sqrt(sum(x*x for x in a)*sum(y*y for y in b))
    if denom == 0:
        raise ValueError("zero vector")
    return sum(x*y for x,y in zip(a,b))/denom

